  ".pi-thumb { width: 40px; height: 40px; }\n  .tray-item .pi-tools { justify-content: flex-end; }\n\n  /* Search: sources, helper status, result groups */\n  .field-label { margin: 0 0 8px; font-weight: 600; }\n  .sources { margin-bottom: 18px; }\n  .source-note { margin: 10px 0 0; padding: 10px 14px; border-radius: 10px; font-size: .875rem; background: var(--bad-soft); color: var(--bad); }\n  .conn { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; margin-top: 14px; font-size: .8rem; color: var(--muted); }\n  .conn-dot { width: 8px; height: 8px; border-radius: 50%; background: #c9a227; flex: none; }\n  .conn[data-kind=\"local\"] .conn-dot, .conn[data-kind=\"cloud\"] .conn-dot, .conn[data-kind=\"custom\"] .conn-dot { background: var(--ok); }\n  /* Customer projects */\n  .projects {\n    margin: 20px 0 4px; padding: 14px 16px;\n    background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow);\n  }\n  .proj-row { display: flex; flex-wra",
