  "', by: 'none' },\n    mixed: { label: 'หลายแหล่ง', by: 'none' },\n  };\n  const SOURCE_UI = {\n    btv: {\n      label: 'รหัสสินค้าบุญถาวร', placeholder: 'เช่น 1015431',\n      hint: 'ใส่ได้หลายรหัส คั่นด้วยเว้นวรรค จุลภาค หรือขึ้นบรรทัดใหม่ (Shift+Enter) · วางลิงก์หน้าสินค้าก็ได้',\n      examples: [['1015431', '1015431'], ['หลายรหัส', '1015431, 1068468, 1252051']],\n    },\n    homepro: {\n      label: 'รหัสสินค้า HomePro', placeholder: 'เช่น 1310224',\n      hint: 'รหัสสินค้าจากหน้าสินค้า HomePro ใส่ได้หลายรหัส · วางลิงก์หน้าสินค้าก็ได้',\n      examples: [['1310224', '1310224']],\n    },\n    traphet: {\n      label: 'ชื่อสินค้าตราเพชร', placeholder: 'เช่น ครอบสันโค้ง',\n      hint: 'เว็บนี้ไม่มีรหัสสินค้า ค้นหาด้วยชื่อแทน · ค้นหาหลายชื่อได้โดยขึ้นบรรทัดใหม่ (Shift+Enter) แล้วกด “เพิ่มลงงานนำเสนอ” ที่สินค้าที่ต้องการ',\n      examples: [['ครอบสันโค้ง', 'ครอบสันโค้ง'], ['กระเบื้องลอนคู่', 'กระเบื้องลอนคู่']],\n    },\n    ecodoor: {\n      label: 'ชื่อสินค้า Eco door', placeholder: 'เช่น ประตูไฟเบอร์กล",
