  "    }).join('')}</ol>`;\n  }\n\n  function itemMeta(it) {\n    const v = it.view;\n    if (isSet(it)) return esc(`ชุด ${it.members.length} รายการ: ${it.members.map((m) => m.label).join(', ')}`);\n    return [sourceLabel(v) || SOURCES.custom.label, v.sku ? 'รหัส ' + v.sku : '', v.brand, v.final != null ? (v.priceFrom ? 'เริ่มต้น ' : '') + money(v.final) + ' บาท' : '']\n      .filter(Boolean).map(esc).join(' · ');\n  }\n\n  function renderPages() {\n    const products = [...pool.values()].filter((it) => !isSet(it)).length;\n    deckCountEl.innerHTML = `สินค้า <strong>${products}</strong> รายการ · <strong>${pages.length}</strong> หน้า + ปก`;\n    const starts = pageStarts();\n    pagesEl.innerHTML = pages.map((p, i) => renderPage(p, i, starts.get(p.id))).join('') || '<p class=\"sub\">ยังไม่มีหน้า กด “+ เพิ่มหน้า”</p>';\n    renderTray();\n    refreshAddButtons();\n    toDeckBtn.hidden = pool.size === 0;\n    scheduleSave();\n  }\n\n  function renderPage(p, idx, { start, carry }) {\n    const max = maxFor(p);\n   ",
  " const isPlacing = placing && placing.pageId === p.id;\n    const selected = selection.pageId === p.id ? selection.keys : new Set();\n    const items = p.keys.map((key, n) => {\n      const it = pool.get(key);\n      const v = it.view;\n      const set = isSet(it);\n      const mark = p.marks[key];\n      const picking = isPlacing && placing.key === key;\n      const pointTools = p.withImage && p.image\n        ? `<button class=\"btn-sm${picking ? ' is-on' : ''}\" type=\"button\" data-act=\"mark\">${picking ? 'กำลังเลือกตำแหน่ง…' : mark ? 'ชี้ตำแหน่งใหม่' : 'ชี้ในภาพ'}</button>\n           ${mark ? '<button class=\"btn-sm btn-sm--plain\" type=\"button\" data-act=\"unmark\">ลบตัวชี้</button>' : ''}`\n        : '';\n      return `<div class=\"pi${set ? ' pi--set' : ''}${selected.has(key) ? ' is-selected' : ''}\" data-key=\"${esc(key)}\">\n        <input class=\"pi-check\" type=\"checkbox\" data-act=\"select\"${selected.has(key) ? ' checked' : ''} aria-label=\"เลือก ${esc(v.name)} เพื่อรวมเป็นชุด\">\n        <span class=\"pi-n",
