  "\n  // white square), so the pictures of a combined picture can sit side by side or overlap neatly.\n  async function trimWhite(img) {\n    const im = await loadImageEl(img.data);\n    const c = document.createElement('canvas');\n    c.width = img.w;\n    c.height = img.h;\n    const ctx = c.getContext('2d');\n    ctx.drawImage(im, 0, 0, img.w, img.h);\n    const px = ctx.getImageData(0, 0, img.w, img.h).data;\n    let x0 = img.w, y0 = img.h, x1 = -1, y1 = -1;\n    for (let y = 0; y < img.h; y += 2) {\n      for (let x = 0; x < img.w; x += 2) {\n        const i = (y * img.w + x) * 4;\n        if (px[i] < 238 || px[i + 1] < 238 || px[i + 2] < 238) {\n          if (x < x0) x0 = x;\n          if (x > x1) x1 = x;\n          if (y < y0) y0 = y;\n          if (y > y1) y1 = y;\n        }\n      }\n    }\n    if (x1 < 0) return img;\n    const pad = Math.round(Math.max(img.w, img.h) * 0.02);\n    x0 = Math.max(0, x0 - pad); y0 = Math.max(0, y0 - pad);\n    x1 = Math.min(img.w - 1, x1 + pad); y1 = Math.min(img.h - 1, y",
