  "onst CONTENT_TOP = 1.15;\n  const CONTENT_BOTTOM = 6.6;\n  const COL = { navy: '13234B', navy2: '22365F', gold: 'B8935A', goldLight: 'DCC08A', red: 'D0312D', ink: '1F1F1F', muted: '5C5C5C', rule: '7F7F7F', soft: 'F4F1EA', price: 'D9541E' };\n  const FONT_HEAD = 'Kanit';\n  const FONT_BODY = 'Sarabun';\n  const LONG_ATTRS = new Set(['features', 'maintenance', 'care_warning_instruction']);\n  const COVER_NOTE = [\n    'เอกสารสรุปและยืนยันรายการวัสดุเบื้องต้นตามที่ลูกค้าได้เลือกไว้',\n    'ยังไม่ถือเป็นการสั่งซื้อและการจองสินค้า',\n    'การสั่งซื้อจะดำเนินการตามขั้นตอนของบริษัทฯ',\n    'เมื่อถึงกำหนดสั่งซื้อจริง',\n  ];\n  const DISCLAIMER = [\n    'รายการวัสดุในเอกสารฉบับนี้จัดทำขึ้นเพื่อสรุปและยืนยันรายการวัสดุเบื้องต้นตามที่ได้เลือกไว้เท่านั้น ยังไม่ถือเป็นการสั่งซื้อหรือการจองสินค้า',\n    'การสั่งซื้อจะดำเนินการตามขั้นตอนของบริษัทเมื่อถึงกำหนดสั่งซื้อจริง ทั้งนี้ รุ่น สี ขนาด ราคา และความพร้อมของสินค้าอาจมีการเปลี่ยนแปลง ณ วันที่สั่งซื้อจริง',\n  ];\n\n  function fitBox(img, x, y, w, h, align = 'cent",
  "er') {\n    const r = Math.min(w / img.w, h / img.h);\n    const iw = img.w * r;\n    const ih = img.h * r;\n    return { x: align === 'left' ? x : x + (w - iw) / 2, y: y + (h - ih) / 2, w: iw, h: ih };\n  }\n\n  // An item's picture in the box: one picture, or a combined one made of the main product and its\n  // accessories, each a separate picture so it stays editable in Canva. A tall main product (a door)\n  // gets its accessories beside it; a square or wide one (a tile) gets them in its lower right corner.\n  // Returns the main picture's box.\n  function addPictures(s, S, pics, x, y, w, h) {\n    const [main, ...rest] = pics;\n    if (!main) return null;\n    if (!rest.length) {\n      const r = fitBox(main, x, y, w, h);\n      s.addImage({ data: main.data, ...r });\n      return r;\n    }\n    if (main.w / main.h < 0.8) {\n      const gap = Math.min(w, h) * 0.05;\n      const r = fitBox(main, x, y, Math.min(w * 0.6, h * main.w / main.h), h);\n      s.addImage({ data: main.data, ...r });\n      const ",
