  " (x2,y2); the arrow head (if any) sits at (x2,y2).\n  function drawLine(s, S, x1, y1, x2, y2, line) {\n    const o = { x: Math.min(x1, x2), y: Math.min(y1, y2), w: Math.abs(x2 - x1), h: Math.abs(y2 - y1), line };\n    if (x2 < x1) o.flipH = true;\n    if (y2 < y1) o.flipV = true;\n    s.addShape(S.line, o);\n  }\n\n  function numberBadge(s, S, n, x, y, d, fill) {\n    s.addText(String(n), {\n      shape: S.ellipse, x, y, w: d, h: d, fill: { color: fill }, line: { type: 'none' },\n      color: 'FFFFFF', fontFace: FONT_BODY, fontSize: d < 0.3 ? 8 : 9, bold: true, align: 'center', valign: 'middle', margin: 0,\n    });\n  }\n\n  function buildDeck(PptxGenJS, info, slidePages, opts) {\n    const pptx = new PptxGenJS();\n    pptx.defineLayout({ name: 'A4L', width: SW, height: SH });\n    pptx.layout = 'A4L';\n    pptx.theme = { headFontFace: FONT_HEAD, bodyFontFace: FONT_BODY };\n    pptx.title = 'Material Selection Confirmation' + (info.project ? ' - ' + info.project : '');\n    if (info.preparer) pptx.author =",
  " info.preparer;\n    if (info.company) pptx.company = info.company;\n    const S = pptx.ShapeType;\n    addCover(pptx, S, info, opts);\n    for (const page of slidePages) addMaterialSlide(pptx, S, info, page, opts);\n    return { pptx, slides: slidePages.length + 1 };\n  }\n\n  function addCover(pptx, S, info, opts) {\n    const s = pptx.addSlide();\n    s.background = { color: COL.navy };\n    const px = COVER_PHOTO_X;\n    const by = COVER_BAR_Y;\n\n    if (opts.cover) {\n      s.addImage({ data: opts.cover.data, x: px, y: 0, w: SW - px, h: by });\n    } else {\n      s.addText('ใส่รูปภาพโครงการ', {\n        shape: S.rect, x: px, y: 0, w: SW - px, h: by, fill: { color: COL.navy2 }, line: { type: 'none' },\n        align: 'center', valign: 'middle', fontFace: FONT_BODY, fontSize: 14, color: COL.goldLight,\n      });\n    }\n\n    // White panel with a diagonal right edge, edged in gold.\n    s.addShape(S.rect, { x: 0, y: 0, w: px, h: by, fill: { color: 'FFFFFF' }, line: { type: 'none' } });\n    s.addShape(S.",
