  " 9, bold: true, align: 'center', valign: 'middle', margin: 0,\n        });\n      }\n    });\n  }\n\n  // \"จำนวน 25 กล่อง\", or '' when no quantity was entered.\n  function qtyText(qty, unit) {\n    const q = String(qty || '').trim();\n    return q ? `จำนวน ${q}${unit ? ' ' + unit : ''}` : '';\n  }\n\n  // \"รหัส 123 · 120 บาท / แผ่น · จำนวน 25 กล่อง\" for one product of a set.\n  function variantDetail(m, f) {\n    const v = m.view;\n    return [\n      f.sku && v.sku ? 'รหัส ' + v.sku : '',\n      f.price && v.final != null ? priceText(v) : '',\n      f.qty ? qtyText(m.qty, m.qtyUnit || v.unit) : '',\n    ].filter(Boolean).join(' · ');\n  }\n\n  // Table rows for a one-item page. `required` rows are never dropped to save space.\n  function detailRows(it, f, usageRow) {\n    const v = it.view;\n    const rows = [];\n    const add = (k, val, required = true) => rows.push({ k, val, required });\n    if (it.members && it.style === 'combo') {\n      // The main product's details, then one row per accessory (\"ยาแนวที่ใช",
