  "face-2); font-family: inherit; font-size: .9em; font-weight: 600; white-space: nowrap; }\n  code { font-family: ui-monospace, Consolas, monospace; font-size: .9em; padding: 1px 6px; border-radius: 5px; background: var(--surface-2); }\n  .tip, .warn { margin: 12px 0 0; padding: 12px 14px; border-radius: 10px; font-size: .95rem; }\n  .tip { background: var(--accent-soft); }\n  .warn { background: var(--warn-soft); }\n  .tip strong, .warn strong { display: block; }\n  .skip { margin: 8px 0; padding: 12px 16px; border-left: 4px solid var(--accent); background: var(--surface); border-radius: 0 10px 10px 0; }\n\n  /* Mock screens (illustrations, not real screenshots) */\n  .mock { margin: 14px 0 4px; border: 1px solid #c9c6bf; border-radius: 10px; overflow: hidden; background: #fff; color: #1d1d1b; font-size: .9rem; box-shadow: 0 2px 10px rgba(0, 0, 0, .08); max-width: 560px; }\n  .mock-bar { display: flex; align-items: center; gap: 6px; padding: 6px 10px; font-size: .8rem; color: #555; background: #f",
